"""
report_generator.py — Downloadable report generation for SecureSight AI.
Produces CSV, Markdown, and HTML reports from real scan data.
All user-supplied content is escaped before insertion into HTML.
"""

from __future__ import annotations
import csv
import html
import io
import json
from datetime import datetime
from typing import Any


APP_NAME = "SecureSight AI"
APP_VERSION = "1.0.0"
DISCLAIMER = (
    "This report was generated by SecureSight AI and represents a configuration-based security posture estimate. "
    "It is not a certified security audit, penetration test, or guarantee of security. "
    "Absence of findings does not mean the assessed site is free of vulnerabilities. "
    "Always engage a qualified security professional for compliance or high-stakes assessments. "
    "Only scan websites you own or are explicitly authorized to assess."
)

SEVERITY_ORDER = ["Critical", "High", "Medium", "Low", "Informational"]


def _escape(text: Any) -> str:
    return html.escape(str(text or ""), quote=True)


def _now_str() -> str:
    return datetime.utcnow().strftime("%Y-%m-%d %H:%M UTC")


# ---------------------------------------------------------------------------
# CSV export
# ---------------------------------------------------------------------------

def generate_csv(findings: list[dict]) -> str:
    output = io.StringIO()
    fieldnames = [
        "id", "check_name", "target", "severity", "confidence",
        "title", "evidence", "explanation", "impact", "recommendation", "status", "created_at",
    ]
    writer = csv.DictWriter(output, fieldnames=fieldnames, extrasaction="ignore")
    writer.writeheader()
    for f in findings:
        writer.writerow({k: f.get(k, "") for k in fieldnames})
    return output.getvalue()


# ---------------------------------------------------------------------------
# Markdown report
# ---------------------------------------------------------------------------

def generate_markdown(scan: dict, findings: list[dict], score: float) -> str:
    lines: list[str] = []
    target = scan.get("target_url", "Unknown")
    scan_id = scan.get("id", "Unknown")
    ts = scan.get("completed_at") or scan.get("started_at") or _now_str()

    lines += [
        f"# {APP_NAME} — Security Assessment Report",
        "",
        "> **NOTICE:** This is a configuration-based assessment, not a certified security audit.",
        "",
        "## Scan Details",
        f"- **Target:** {target}",
        f"- **Scan ID:** {scan_id}",
        f"- **Completed:** {ts}",
        f"- **Report Generated:** {_now_str()}",
        f"- **Tool:** {APP_NAME} {APP_VERSION}",
        "",
        "## Executive Summary",
        "",
        f"**Security Posture Score: {score}/100**",
        "",
    ]

    if score >= 80:
        lines.append("The assessed site demonstrates a relatively good security header configuration.")
    elif score >= 60:
        lines.append("The assessed site has a fair security configuration with some areas for improvement.")
    elif score >= 40:
        lines.append("The assessed site has notable security configuration gaps that should be addressed.")
    else:
        lines.append("The assessed site has significant security configuration weaknesses that require urgent attention.")

    lines += ["", "## Findings Summary", ""]

    from risk_engine import count_by_severity
    counts = count_by_severity(findings)
    for sev in SEVERITY_ORDER:
        lines.append(f"- **{sev}:** {counts.get(sev, 0)}")

    lines += ["", "## Findings Detail", ""]

    for sev in SEVERITY_ORDER:
        sev_findings = [f for f in findings if f.get("severity") == sev]
        if not sev_findings:
            continue
        lines.append(f"### {sev} Severity")
        lines.append("")
        for f in sev_findings:
            lines += [
                f"#### {f.get('title', 'Finding')}",
                f"- **Check:** {f.get('check_name', '')}",
                f"- **Confidence:** {f.get('confidence', '')}",
                f"- **Status:** {f.get('status', 'open')}",
                "",
                f"**Evidence:**",
                f"```",
                f"{f.get('evidence', 'N/A')}",
                f"```",
                "",
                f"**Explanation:** {f.get('explanation', '')}",
                "",
                f"**Impact:** {f.get('impact', '')}",
                "",
                f"**Recommendation:** {f.get('recommendation', '')}",
                "",
                "---",
                "",
            ]

    lines += [
        "## Assessment Scope",
        "",
        "SecureSight AI performs non-destructive HTTP/HTTPS configuration checks including:",
        "- HTTPS usage and TLS certificate validity",
        "- HTTP security response headers",
        "- Basic CORS header configuration",
        "- Response status and timing information",
        "",
        "SecureSight AI does **not** perform penetration testing, exploit execution, password guessing,",
        "port scanning, malware detection, or any destructive testing.",
        "",
        "## Limitations",
        "",
        "- Checks are limited to observable HTTP response headers and certificate metadata.",
        "- Absence of a finding does not mean the site is secure.",
        "- Some findings may be false positives depending on application context.",
        "- TLS configuration depth (cipher suites, protocol versions) is not fully assessed.",
        "",
        "## Authorization Statement",
        "",
        DISCLAIMER,
        "",
        f"*Report generated by {APP_NAME} {APP_VERSION} on {_now_str()}*",
    ]

    return "\n".join(lines)


# ---------------------------------------------------------------------------
# HTML report
# ---------------------------------------------------------------------------

_HTML_SEVERITY_COLORS = {
    "Critical": "#FD9384",
    "High":     "#FD9384",
    "Medium":   "#C8A6F4",
    "Low":      "#8ADAD2",
    "Informational": "#A7B6AC",
}

_HTML_TEMPLATE = """<!DOCTYPE html>
<html lang="en">
<head>
<meta charset="UTF-8">
<meta name="viewport" content="width=device-width, initial-scale=1.0">
<title>SecureSight AI — Security Report</title>
<style>
  :root {{
    --bg: #07110D; --surface: #101F18; --surface2: #15271F;
    --border: #293D32; --text: #F5F7F4; --muted: #A7B6AC;
    --lavender: #C8A6F4; --mint: #8ADAD2; --coral: #FD9384; --forest: #02391C;
  }}
  * {{ box-sizing: border-box; margin: 0; padding: 0; }}
  body {{ background: var(--bg); color: var(--text); font-family: -apple-system, "Segoe UI", system-ui, sans-serif;
         font-size: 14px; line-height: 1.6; padding: 24px; }}
  .container {{ max-width: 900px; margin: 0 auto; }}
  .header {{ border-bottom: 2px solid var(--lavender); padding-bottom: 16px; margin-bottom: 24px; }}
  .logo {{ font-size: 22px; font-weight: 700; color: var(--lavender); }}
  .logo span {{ color: var(--mint); }}
  .meta {{ color: var(--muted); font-size: 13px; margin-top: 6px; }}
  .score-box {{ background: var(--surface); border: 1px solid var(--border); border-radius: 10px;
               padding: 20px 24px; margin-bottom: 20px; display: flex; align-items: center; gap: 24px; }}
  .score-num {{ font-size: 48px; font-weight: 800; color: {score_color}; line-height: 1; }}
  .score-label {{ font-size: 13px; color: var(--muted); }}
  .score-desc {{ font-size: 15px; color: var(--text); }}
  .section {{ margin-bottom: 28px; }}
  .section h2 {{ font-size: 16px; font-weight: 600; color: var(--lavender); border-bottom: 1px solid var(--border);
                padding-bottom: 8px; margin-bottom: 14px; }}
  .section h3 {{ font-size: 14px; font-weight: 600; margin: 16px 0 8px; }}
  .finding {{ background: var(--surface); border: 1px solid var(--border); border-radius: 8px;
              padding: 14px 16px; margin-bottom: 10px; border-left: 3px solid {sev_color_placeholder}; }}
  .severity-badge {{ display: inline-block; padding: 2px 10px; border-radius: 20px; font-size: 12px;
                    font-weight: 600; background: var(--surface2); }}
  .evidence-block {{ background: var(--bg); border: 1px solid var(--border); border-radius: 4px;
                    padding: 8px 12px; font-family: monospace; font-size: 12px; color: var(--mint);
                    margin: 6px 0; white-space: pre-wrap; word-break: break-all; }}
  .label {{ font-weight: 600; color: var(--muted); font-size: 12px; text-transform: uppercase;
           letter-spacing: 0.05em; margin-top: 8px; }}
  .summary-grid {{ display: grid; grid-template-columns: repeat(auto-fit, minmax(140px, 1fr)); gap: 10px; }}
  .summary-card {{ background: var(--surface); border: 1px solid var(--border); border-radius: 8px;
                  padding: 12px 16px; text-align: center; }}
  .summary-card .num {{ font-size: 28px; font-weight: 700; }}
  .summary-card .lbl {{ font-size: 12px; color: var(--muted); }}
  .notice {{ background: var(--surface2); border: 1px solid var(--coral); border-radius: 8px;
            padding: 12px 16px; color: var(--muted); font-size: 13px; margin-bottom: 20px; }}
  .footer {{ border-top: 1px solid var(--border); padding-top: 12px; margin-top: 32px; color: var(--muted); font-size: 12px; }}
</style>
</head>
<body>
<div class="container">
  <div class="header">
    <div class="logo">Secure<span>Sight</span> AI</div>
    <div class="meta">Web Security Configuration Assessment Report</div>
    <div class="meta">Target: {target} &nbsp;|&nbsp; Scan ID: {scan_id} &nbsp;|&nbsp; {scan_ts}</div>
  </div>

  <div class="notice">
    &#x26a0; This report represents a configuration-based posture estimate, not a certified security audit.
    Absence of findings does not mean the site is secure. Only scan sites you own or are authorized to assess.
  </div>

  <div class="score-box">
    <div>
      <div class="score-num">{score}</div>
      <div class="score-label">/ 100</div>
    </div>
    <div>
      <div class="score-desc"><strong>{score_label}</strong> — Security Posture Score</div>
      <div style="color: var(--muted); font-size: 13px; margin-top: 4px;">{score_summary}</div>
    </div>
  </div>

  {summary_html}
  {findings_html}

  <div class="section">
    <h2>Assessment Scope &amp; Limitations</h2>
    <p>SecureSight AI performed non-destructive checks on HTTP/HTTPS response headers,
    TLS certificate metadata, and CORS configuration. It does <strong>not</strong> perform
    penetration testing, exploitation, port scanning, or malware detection.</p>
    <p style="margin-top:8px; color: var(--muted); font-size:13px;">{disclaimer}</p>
  </div>

  <div class="footer">
    Generated by {app_name} {app_version} &nbsp;|&nbsp; {generated_at}
  </div>
</div>
</body>
</html>"""


def generate_html(scan: dict, findings: list[dict], score: float) -> str:
    from risk_engine import count_by_severity, get_posture_label
    target = _escape(scan.get("target_url", "Unknown"))
    scan_id = _escape(scan.get("id", "Unknown"))
    ts = _escape(scan.get("completed_at") or scan.get("started_at") or _now_str())
    score_label, _ = get_posture_label(score)
    counts = count_by_severity(findings)

    if score >= 80:
        score_color = "#8ADAD2"
        score_summary = "The site demonstrates a relatively good security header configuration."
    elif score >= 60:
        score_color = "#C8A6F4"
        score_summary = "The site has a fair configuration with some areas for improvement."
    elif score >= 40:
        score_color = "#FD9384"
        score_summary = "The site has notable security configuration gaps that should be addressed."
    else:
        score_color = "#FD9384"
        score_summary = "The site has significant security weaknesses requiring urgent attention."

    # Summary grid
    summary_cards = ""
    for sev in SEVERITY_ORDER:
        c = counts.get(sev, 0)
        color = _HTML_SEVERITY_COLORS.get(sev, "#A7B6AC")
        summary_cards += (
            f'<div class="summary-card">'
            f'<div class="num" style="color:{color}">{c}</div>'
            f'<div class="lbl">{_escape(sev)}</div>'
            f'</div>'
        )
    summary_html = (
        '<div class="section"><h2>Findings Summary</h2>'
        f'<div class="summary-grid">{summary_cards}</div>'
        '</div>'
    )

    # Findings detail
    findings_html_parts = ['<div class="section"><h2>Findings Detail</h2>']
    for sev in SEVERITY_ORDER:
        sev_findings = [f for f in findings if f.get("severity") == sev]
        if not sev_findings:
            continue
        color = _HTML_SEVERITY_COLORS.get(sev, "#A7B6AC")
        findings_html_parts.append(f'<h3 style="color:{color}">{_escape(sev)} Severity ({len(sev_findings)})</h3>')
        for f in sev_findings:
            findings_html_parts.append(
                f'<div class="finding" style="border-left-color:{color}">'
                f'<div style="display:flex;align-items:center;gap:10px;margin-bottom:8px;">'
                f'<span class="severity-badge" style="color:{color}">{_escape(f.get("severity",""))}</span>'
                f'<strong>{_escape(f.get("title",""))}</strong>'
                f'</div>'
                f'<div class="label">Check</div><div>{_escape(f.get("check_name",""))}</div>'
                f'<div class="label">Confidence</div><div>{_escape(f.get("confidence",""))}</div>'
                f'<div class="label">Evidence</div>'
                f'<div class="evidence-block">{_escape(f.get("evidence","N/A"))}</div>'
                f'<div class="label">Explanation</div><div>{_escape(f.get("explanation",""))}</div>'
                f'<div class="label">Potential Impact</div><div>{_escape(f.get("impact",""))}</div>'
                f'<div class="label">Recommendation</div><div style="color:#8ADAD2">{_escape(f.get("recommendation",""))}</div>'
                f'</div>'
            )
    findings_html_parts.append('</div>')
    findings_html = "\n".join(findings_html_parts)

    html_out = _HTML_TEMPLATE.format(
        target=target, scan_id=scan_id, scan_ts=ts,
        score=score, score_color=score_color,
        score_label=_escape(score_label), score_summary=_escape(score_summary),
        summary_html=summary_html,
        findings_html=findings_html,
        disclaimer=_escape(DISCLAIMER),
        app_name=APP_NAME, app_version=APP_VERSION,
        generated_at=_now_str(),
        sev_color_placeholder="#293D32",
    )
    return html_out
